// Built-in file types - parsed from TYPE_LIST_TXT for functionality
// Also need to support --type-add etc.

// We'll store type definitions as map from type name to Vec<Glob>
// Parse TYPE_LIST_TXT lines like "rust: *.rs"
// Actually format is "type: glob1, glob2"

fn parse_builtin_types() -> HashMap<String, Vec<String>> {
    let mut map: HashMap<String, Vec<String>> = HashMap::new();
    for line in TYPE_LIST_TXT.lines() {
        if line.trim().is_empty() { continue; }
        if let Some(idx) = line.find(": ") {
            let name = line[..idx].trim().to_string();
            let globs_part = line[idx+2..].trim();
            if globs_part.is_empty() { continue; }
            let globs: Vec<String> = globs_part.split(',').map(|s| s.trim().to_string()).filter(|s| !s.is_empty()).collect();
            map.insert(name, globs);
        }
    }
    map
}

