fn parse_filesize(s: &str) -> Option<u64> {
    let s = s.trim();
    if s.is_empty() { return None; }
    let mut num_part = String::new();
    let mut suffix_part = String::new();
    for c in s.chars() {
        if c.is_ascii_digit() {
            if suffix_part.is_empty() {
                num_part.push(c);
            } else {
                // digit after suffix invalid
                return None;
            }
        } else {
            suffix_part.push(c);
        }
    }
    if num_part.is_empty() { return None; }
    let num: u64 = num_part.parse().ok()?;
    let mult = match suffix_part.to_ascii_lowercase().as_str() {
        "" => 1,
        "k" => 1024,
        "m" => 1024*1024,
        "g" => 1024*1024*1024,
        "ki" | "kib" => 1024,
        "mi" | "mib" => 1024*1024,
        "gi" | "gib" => 1024*1024*1024,
        _ => return None,
    };
    Some(num * mult)
}

fn parse_args(raw_args: Vec<String>) -> Result<Options, String> {
    let mut opts = Options::default();
    let mut i = 0;
    let mut pattern_first: Option<String> = None;
    let mut seen_double_dash = false;
    let mut positional: Vec<String> = Vec::new();

    // For handling config file args: they are already prepended before raw_args parsing.
    // We'll parse raw_args which includes config file args + cli args.

    while i < raw_args.len() {
        let arg = &raw_args[i];
        if seen_double_dash {
            positional.push(arg.clone());
            i+=1;
            continue;
        }
        if arg == "--" {
            seen_double_dash = true;
            i+=1;
            continue;
        }
