            // long flag
            let (key, val_opt) = if let Some(eq_idx) = arg.find('=') {
                (arg[..eq_idx].to_string(), Some(arg[eq_idx+1..].to_string()))
            } else {
                (arg.clone(), None)
            };
            match key.as_str() {
                "--regexp" | "--regexp=" => {
                    let val = if let Some(v) = val_opt { v } else { i+=1; if i>=raw_args.len() { return Err(format!("flag {} requires argument", key)); } raw_args[i].clone() };
                    opts.patterns.push(val);
                },
                "--file" => {
                    let val = if let Some(v) = val_opt { v } else { i+=1; if i>=raw_args.len() { return Err(format!("flag {} requires argument", key)); } raw_args[i].clone() };
                    opts.pattern_files.push(val);
                },
                "--pre" => {
                    let val = if let Some(v) = val_opt { v } else { i+=1; if i>=raw_args.len() { return Err(format!("flag {} requires argument", key)); } raw_args[i].clone() };
                    opts.pre = Some(val);
                },
                "--pre-glob" => {
                    let val = if let Some(v) = val_opt { v } else { i+=1; if i>=raw_args.len() { return Err(format!("flag {} requires argument", key)); } raw_args[i].clone() };
                    opts.pre_glob.push(val);
                },
                "--search-zip" => opts.search_zip = true,
                "--no-search-zip" => opts.search_zip = false,
                "--case-sensitive" => opts.case_sensitive = Some(true),
                "--no-case-sensitive" => opts.case_sensitive = Some(false),
                "--crlf" => opts.crlf = true,
                "--no-crlf" => opts.crlf = false,
                "--dfa-size-limit" => {
                    let val = if let Some(v) = val_opt { v } else { i+=1; if i>=raw_args.len() { return Err(format!("flag {} requires argument", key)); } raw_args[i].clone() };
                    // ignore
                },
                "--encoding" => {
                    let val = if let Some(v) = val_opt { v } else { i+=1; if i>=raw_args.len() { return Err(format!("flag {} requires argument", key)); } raw_args[i].clone() };
                    opts.encoding = Some(val);
                },
                "--no-encoding" => opts.encoding = None,
                "--engine" => {
                    let val = if let Some(v) = val_opt { v } else { i+=1; if i>=raw_args.len() { return Err(format!("flag {} requires argument", key)); } raw_args[i].clone() };
                    opts.engine = Some(val);
                },
                "--fixed-strings" => opts.fixed_strings = true,
                "--no-fixed-strings" => opts.fixed_strings = false,
                "--ignore-case" => opts.case_sensitive = Some(false),
                "--no-ignore-case" => opts.case_sensitive = Some(true),
                "--invert-match" => opts.invert_match = true,
                "--no-invert-match" => opts.invert_match = false,
