                    let unescaped = unescape_separator(&val);
                    if unescaped.len() != 1 {
                        // error handling similar to rg: error parsing flag --path-separator
                        return Err(format!("error parsing flag --path-separator: A path separator must be exactly one byte, but the given separator is {} bytes: {}", unescaped.len(), val));
                    }
                    opts.path_separator = Some(unescaped.as_bytes()[0]);
                },
                "--passthru" => opts.passthru = true,
                "--no-passthru" => opts.passthru = false,
                "--pretty" => opts.pretty = true,
                "--no-pretty" => opts.pretty = false,
                "--quiet" => opts.quiet = true,
