                    // So: if context is Some, then before = context, after = context, unless -A or -B provided they override corresponding.
                    // We already have before_context and after_context separate, and context Option. So effective:
                    let eff_before = if opts.context.is_some() {
                        if opts.before_context != 0 || opts.context.unwrap() != 0 && (/* we need to know if -B was explicitly given */ true) {
