                    } else {
                        opts.before_context
                    };
                    let eff_after = if opts.context.is_some() {
                        if opts.after_context > 0 { opts.after_context } else { opts.context.unwrap() }
                    } else {
                        opts.after_context
                    };
                    // Now merge
                    let mut to_print: Vec<(usize, bool)> = Vec::new(); // (line_index, is_match)
                    let mut last_printed = None;
                    let mut chunks: Vec<Vec<(usize, bool)>> = Vec::new();
                    let mut current_chunk: Vec<(usize, bool)> = Vec::new();

                    // Create a set of match line numbers (0-indexed)
                    let match_line_numbers: std::collections::HashSet<usize> = result.matches.iter().map(|m| m.line_number - 1).collect();

                    // For each match, create range
                    let mut ranges: Vec<(usize, usize)> = Vec::new();
                    for m in &result.matches {
                        let idx = m.line_number - 1;
                        let start = idx.saturating_sub(eff_before);
                        let end = (idx + eff_after).min(all_lines.len().saturating_sub(1));
                        ranges.push((start, end));
                    }
                    // Merge ranges and sort
                    ranges.sort_by_key(|r| r.0);
                    let mut merged: Vec<(usize, usize)> = Vec::new();
                    for r in ranges {
                        if let Some(last) = merged.last_mut() {
                            if r.0 <= last.1 + 1 {
                                last.1 = last.1.max(r.1);
                            } else {
                                merged.push(r);
                            }
                        } else {
                            merged.push(r);
                        }
                    }

                    // Now for each merged range, print lines with context separators between chunks
                    for (chunk_idx, (start, end)) in merged.iter().enumerate() {
