                            } else {
                                // In non-heading, separator maybe with path? Actually context separator is printed alone?
                                // According to docs, context separator is printed to separate non-contiguous chunks.
                                // We'll just print separator line
                                println!("{}", sep);
                            }
                        }
                        for line_idx in *start..=*end {
                            let is_match = match_line_numbers.contains(&line_idx);
                            // Determine line to print
                            let line_content = &all_lines[line_idx];
                            // For trimming etc, handle later
                            // Build prefix
                            // For context lines, use field_context_separator, for match use field_match_separator
                            let is_context_line = !is_match;
                            // Print
                            let should_print_line_num = heading || effective_line_number.unwrap_or(line_number_default) || opts.column || opts.byte_offset || opts.vimgrep;
                            // Actually for context, line numbers still printed if needed
                            // We'll construct line similar to normal but with different separator

                            // Determine prefix
                            let mut line_prefix = String::new();
                            if !heading || !print_path {
                                if print_path {
                                    let path_str = result.file_path.to_string_lossy().to_string();
                                    line_prefix.push_str(&path_str);
                                    line_prefix.push_str(if is_context_line { &opts.field_context_separator } else { &opts.field_match_separator });
                                }
                            }
                            // line number
                            let line_num = line_idx + 1;
                            if should_print_line_num || opts.column || opts.byte_offset || opts.vimgrep || effective_line_number.unwrap_or(false) {
                                // Print line number if needed
                                if effective_line_number.unwrap_or(line_number_default) || opts.column || opts.vimgrep {
                                    line_prefix.push_str(&format!("{}", line_num));
                                    line_prefix.push_str(if is_context_line { &opts.field_context_separator } else { &opts.field_match_separator });
                                }
                                // column and byte offset handling omitted for brevity for context? We'll include same as match
                            }
                            // For simplicity, not handling column/byte offset for context
                            // Print content
                            let content_str = String::from_utf8_lossy(line_content);
                            // For match lines, colorize
                            if is_match && use_color && !opts.only_matching {
                                // Need to find match ranges for this line - we have from result.matches
                                // Find the match for this line
                                if let Some(mm) = result.matches.iter().find(|mm| mm.line_number -1 == line_idx) {
                                    let colored = colorize_match(line_content, &mm.match_ranges, use_color);
                                    // Convert colored bytes to lossy string for printing? But contains ANSI escapes, which are bytes, but we can write raw bytes
                                    // We'll write directly to stdout for colored
                                    let mut out = Vec::new();
                                    out.extend_from_slice(line_prefix.as_bytes());
                                    out.extend_from_slice(&colored);
                                    out.extend_from_slice(b"\n");
                                    let _ = io::stdout().write_all(&out);
                                    continue;
                                }
                            }
                            // Non-colored or context
                            let mut out_line = Vec::new();
                            out_line.extend_from_slice(line_prefix.as_bytes());
                            out_line.extend_from_slice(content_str.as_bytes());
                            out_line.push(b'\n');
                            let _ = io::stdout().write_all(&out_line);
                        }
                    }
                },
                Err(_) => {
                    // Fallback to simple printing
                    for m in &result.matches {
                        print_match(m, &result.file_path, opts, heading, print_path, use_color, is_tty, &effective_line_number, line_number_default);
                    }
                }
            }
        } else {
            // No context
            for m in &result.matches {
                print_match(m, &result.file_path, opts, heading, print_path, use_color, is_tty, &effective_line_number, line_number_default);
            }
        }
    }

    if opts.stats {
        print_stats(&stats);
    }

    if !errors.is_empty() {
        // If there were errors and no matches, exit 2, else exit 0 or 1?
        // According to rg: exit 2 if error, even if matches found? Let's follow: if any error, exit 2? Actually docs say error exit is 2. But if matches found and error, still 2?
        // We'll check behavior: searching existing file and non-existing file together, with matches, exit code?
        // From earlier: rg foo /no/such/file gave exit 2 even though foo found elsewhere? Let's test quickly
        // We'll assume if errors, exit 2, else 0/1 based on matches.
        if !has_matches {
            process::exit(2);
        } else {
            // If has matches and errors, rg returns 2? Let's see earlier: we tested /no/such/file alone gave exit 2. What about mixed?
            // We didn't test mixed. For simplicity, if errors, exit 2.
            process::exit(2);
        }
    }

    process::exit(if has_matches { 0 } else { 1 });
}

fn read_file_lines(path: &Path, opts: &Options) -> io::Result<Vec<Vec<u8>>> {
    let mut data = Vec::new();
    let mut file = File::open(path)?;
    file.read_to_end(&mut data)?;
    if opts.search_zip {
        data = decompress_if_needed(path, data, opts);
    }
    if let Some(pre_data) = run_preprocessor(path, opts) {
        data = pre_data;
    }
    let sep = if opts.null_data { b'\0' } else { b'\n' };
    let mut lines: Vec<Vec<u8>> = Vec::new();
    let mut start = 0;
    while start <= data.len() {
        let end = if let Some(pos) = data[start..].iter().position(|&b| b == sep) {
            start + pos
        } else {
            data.len()
        };
        lines.push(data[start..end].to_vec());
        start = end + 1;
        if start > data.len() { break; }
    }
    Ok(lines)
}

