                },
                "--max-columns-preview" => opts.max_columns_preview = true,
                "--no-max-columns-preview" => opts.max_columns_preview = false,
                "--null" => opts.null = true,
                "--no-null" => opts.null = false,
                "--only-matching" => opts.only_matching = true,
                "--no-only-matching" => opts.only_matching = false,
                "--path-separator" => {
