                    let val = if let Some(v) = val_opt { v } else { i+=1; if i>=raw_args.len() { return Err(format!("flag {} requires argument", key)); } raw_args[i].clone() };
                    opts.generate = Some(val);
                },
                "--no-config" => opts.no_config = true,
                "--pcre2-version" => opts.pcre2_version = true,
                "--type-list" => opts.type_list = true,
                "--version" => opts.version = true,
                "--help" => opts.help = true,
                _ => {
                    // Unknown long flag: check if it's --no-... for boolean flags not explicitly handled
                    // For simplicity, if it starts with --no-, try to strip and set false if known
                    // Otherwise error?
                    // For ripgrep, unknown flag should error.
                    // We'll try to parse --no-* generically.
                    if key.starts_with("--no-") {
                        let base = format!("--{}", &key[5..]);
                        // We'll recursively handle? For simplicity, treat as unknown but ignore.
                        // To match rg behavior, unknown flag should produce error: "unrecognized flag"
                        // We'll return error.
                        return Err(format!("unrecognized flag: {}", key));
                    } else if key.starts_with("--") {
                        // Unknown flag
                        // Check if it's like --color=...
                        // If we didn't match, error
                        return Err(format!("unrecognized flag: {}", key));
                    } else {
                        unreachable!()
                    }
                }
            }
            i+=1;
        } else if arg.starts_with("-") && arg.len() > 1 {
            // short flags, possibly grouped
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut j = 0;
            while j < chars.len() {
                let c = chars[j];
                match c {
                    'e' => {
                        // needs arg
                        let rest = if j+1 < chars.len() {
                            arg[j+2..].to_string()
                        } else {
                            i+=1;
                            if i>=raw_args.len() { return Err(format!("flag -e requires argument")); }
                            raw_args[i].clone()
                        };
                        opts.patterns.push(rest);
                        break;
                    },
                    'f' => {
                        let rest = if j+1 < chars.len() {
                            arg[j+2..].to_string()
                        } else {
                            i+=1;
                            if i>=raw_args.len() { return Err(format!("flag -f requires argument")); }
                            raw_args[i].clone()
                        };
                        opts.pattern_files.push(rest);
                        break;
                    },
                    'z' => opts.search_zip = true,
                    's' => opts.case_sensitive = Some(true),
                    'F' => opts.fixed_strings = true,
                    'i' => opts.case_sensitive = Some(false),
                    'v' => opts.invert_match = true,
                    'x' => opts.line_regexp = true,
                    'm' => {
                        let rest = if j+1 < chars.len() {
                            arg[j+2..].to_string()
                        } else {
                            i+=1;
                            if i>=raw_args.len() { return Err(format!("flag -m requires argument")); }
                            raw_args[i].clone()
                        };
                        opts.max_count = rest.parse().ok();
                        break;
                    },
                    'U' => opts.multiline = true,
                    'a' => opts.text = true,
                    'j' => {
                        let rest = if j+1 < chars.len() {
                            arg[j+2..].to_string()
                        } else {
                            i+=1;
                            if i>=raw_args.len() { return Err(format!("flag -j requires argument")); }
                            raw_args[i].clone()
                        };
                        opts.threads = rest.parse().ok();
                        break;
                    },
                    'w' => opts.word_regexp = true,
                    'P' => opts.pcre2 = true,
                    'S' => opts.smart_case = true,
                    'L' => opts.follow = true,
                    'g' => {
                        let rest = if j+1 < chars.len() {
                            arg[j+2..].to_string()
                        } else {
                            i+=1;
                            if i>=raw_args.len() { return Err(format!("flag -g requires argument")); }
                            raw_args[i].clone()
                        };
                        opts.globs.push((rest, false));
                        break;
                    },
                    '.' => opts.hidden = true,
                    'd' => {
                        let rest = if j+1 < chars.len() {
                            arg[j+2..].to_string()
                        } else {
                            i+=1;
                            if i>=raw_args.len() { return Err(format!("flag -d requires argument")); }
                            raw_args[i].clone()
                        };
                        opts.max_depth = rest.parse().ok();
                        break;
                    },
                    't' => {
                        let rest = if j+1 < chars.len() {
                            arg[j+2..].to_string()
                        } else {
                            i+=1;
                            if i>=raw_args.len() { return Err(format!("flag -t requires argument")); }
                            raw_args[i].clone()
                        };
                        opts.type_filter.push(rest);
                        break;
                    },
                    'T' => {
                        let rest = if j+1 < chars.len() {
                            arg[j+2..].to_string()
                        } else {
                            i+=1;
                            if i>=raw_args.len() { return Err(format!("flag -T requires argument")); }
                            raw_args[i].clone()
                        };
                        opts.type_not_filter.push(rest);
                        break;
                    },
                    'u' => opts.unrestricted += 1,
                    'A' => {
                        let rest = if j+1 < chars.len() {
                            arg[j+2..].to_string()
                        } else {
                            i+=1;
                            if i>=raw_args.len() { return Err(format!("flag -A requires argument")); }
                            raw_args[i].clone()
                        };
                        opts.after_context = rest.parse().unwrap_or(0);
                        break;
                    },
                    'B' => {
                        let rest = if j+1 < chars.len() {
                            arg[j+2..].to_string()
                        } else {
                            i+=1;
                            if i>=raw_args.len() { return Err(format!("flag -B requires argument")); }
                            raw_args[i].clone()
                        };
                        opts.before_context = rest.parse().unwrap_or(0);
                        break;
                    },
                    'b' => opts.byte_offset = true,
                    'C' => {
                        let rest = if j+1 < chars.len() {
                            arg[j+2..].to_string()
                        } else {
                            i+=1;
                            if i>=raw_args.len() { return Err(format!("flag -C requires argument")); }
                            raw_args[i].clone()
                        };
                        opts.context = rest.parse().ok();
                        break;
                    },
                    'c' => opts.count = true,
                    'l' => opts.files_with_matches = true,
                    'p' => opts.pretty = true,
                    'q' => opts.quiet = true,
                    'r' => {
                        let rest = if j+1 < chars.len() {
                            arg[j+2..].to_string()
                        } else {
                            i+=1;
                            if i>=raw_args.len() { return Err(format!("flag -r requires argument")); }
                            raw_args[i].clone()
                        };
                        opts.replace = Some(rest);
                        break;
                    },
                    'n' => opts.line_number = Some(true),
                    'N' => opts.line_number = Some(false),
                    'M' => {
                        let rest = if j+1 < chars.len() {
                            arg[j+2..].to_string()
                        } else {
                            i+=1;
                            if i>=raw_args.len() { return Err(format!("flag -M requires argument")); }
                            raw_args[i].clone()
                        };
                        opts.max_columns = rest.parse().ok();
                        break;
                    },
                    '0' => opts.null = true,
                    'o' => opts.only_matching = true,
                    'H' => opts.with_filename = Some(true),
                    'I' => {
                        opts.with_filename = Some(false);
                        opts.no_filename = true;
                    },
                    'h' => {
                        opts.short_help = true;
                        // -h alone shows short help, not long
                        break;
                    },
                    'V' => {
                        opts.version = true;
                        break;
                    },
                    'E' => {
                        let rest = if j+1 < chars.len() {
                            arg[j+2..].to_string()
                        } else {
                            i+=1;
                            if i>=raw_args.len() { return Err(format!("flag -E requires argument")); }
                            raw_args[i].clone()
                        };
                        opts.encoding = Some(rest);
                        break;
                    },
                    _ => {
                        return Err(format!("unrecognized flag: -{}", c));
                    }
                }
                j+=1;
            }
            i+=1;
        } else {
            positional.push(arg.clone());
            i+=1;
        }
    }

    // Now positional handling: pattern and paths
    // If patterns provided via -e or -f, then all positionals are paths.
    // Else first positional is pattern, rest are paths.
    if !opts.patterns.is_empty() || !opts.pattern_files.is_empty() {
        for p in positional {
            opts.paths.push(PathBuf::from(p));
        }
    } else {
        if !positional.is_empty() {
            if pattern_first.is_none() {
                // first is pattern
                let pat = positional.remove(0);
                opts.patterns.push(pat);
            }
        }
        for p in positional {
            opts.paths.push(PathBuf::from(p));
        }
    }

    Ok(opts)
}

fn unescape_separator(s: &str) -> String {
    // Handle escape sequences like \x7F or \t \n etc? For simplicity handle \t \n \r \x..
    // rg supports escape sequences. We'll implement simple.
    let mut result = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            if let Some(&next) = chars.peek() {
                match next {
                    'n' => { result.push('\n'); chars.next(); },
                    'r' => { result.push('\r'); chars.next(); },
                    't' => { result.push('\t'); chars.next(); },
                    'x' => {
                        chars.next();
                        // read up to 2 hex digits? Actually rg supports \x7F etc.
                        let mut hex = String::new();
                        for _ in 0..2 {
                            if let Some(&h) = chars.peek() {
                                if h.is_ascii_hexdigit() {
                                    hex.push(h);
                                    chars.next();
                                } else { break; }
                            }
                        }
                        if !hex.is_empty() {
                            if let Ok(byte) = u8::from_str_radix(&hex, 16) {
                                result.push(byte as char);
                            }
                        }
                    },
                    _ => {
                        // for simplicity, just push next char
                        result.push(next);
                        chars.next();
                    }
                }
            } else {
                result.push('\\');
            }
        } else {
            result.push(c);
        }
    }
    result
}

fn read_config_file(path: &Path) -> Vec<String> {
    let mut args = Vec::new();
    if let Ok(content) = fs::read_to_string(path) {
        for line in content.lines() {
            let line = line.trim();
            if line.is_empty() { continue; }
            if line.starts_with('#') { continue; }
            // Split shell argument? For simplicity, each line is one arg, but may contain spaces? According to rg docs: one shell argument per line.
            // So we take line as single arg.
            args.push(line.to_string());
        }
    }
    args
}

fn build_patterns(opts: &Options) -> Result<Vec<String>, String> {
    let mut patterns = Vec::new();
    for pat in &opts.patterns {
        patterns.push(pat.clone());
    }
    for file_path in &opts.pattern_files {
        if file_path == "-" {
            // read from stdin
            let stdin = io::stdin();
            for line in stdin.lock().lines() {
                let line = line.unwrap_or_default();
                patterns.push(line);
            }
        } else {
            let content = fs::read_to_string(file_path).map_err(|e| format!("failed to read pattern file {}: {}", file_path, e))?;
            for line in content.lines() {
                patterns.push(line.to_string());
            }
        }
    }
    Ok(patterns)
}

fn is_binary(data: &[u8]) -> Option<usize> {
    // returns offset of first NUL if binary
    if let Some(pos) = data.iter().position(|&b| b == 0) {
        Some(pos)
    } else {
        None
    }
}

fn build_regex_from_patterns(patterns: &[String], opts: &Options) -> Result<Regex, String> {
    if patterns.is_empty() {
        return Err("no patterns".to_string());
    }
    // If fixed-strings, escape patterns
    let mut combined = String::new();
    for (idx, pat) in patterns.iter().enumerate() {
        if idx > 0 { combined.push('|'); }
        let mut p = pat.clone();
        // Empty pattern matches all lines
        if p.is_empty() {
            // matches all lines: we can use ".*"? But empty pattern in rg matches all lines.
            // We'll handle specially in search: if any pattern empty, match all.
            // For regex, we use ".*"
            combined.push_str(".*");
            continue;
        }
        if opts.fixed_strings {
            p = regex::escape(&p);
        }
        // Handle word-regexp, line-regexp
        if opts.word_regexp {
            // rg's word regexp uses \b? We'll wrap with (?<!\w) and (?!\w) maybe, but using \b
            p = format!(r"\b{}\b", p);
        }
        if opts.line_regexp {
            p = format!(r"^{}$", p);
        }
        combined.push_str(&p);
    }

    // Handle case sensitivity and smart case
    let mut builder = RegexBuilder::new(&combined);
    builder.multi_line(false);
    // For smart case: if pattern contains uppercase, case sensitive, else case insensitive
    let mut case_insensitive = false;
    if let Some(cs) = opts.case_sensitive {
        if !cs {
            case_insensitive = true;
        }
    } else {
        if opts.smart_case {
            // check if any pattern contains uppercase
            let has_upper = patterns.iter().any(|p| p.chars().any(|c| c.is_uppercase()));
            if !has_upper {
                case_insensitive = true;
            }
        }
    }
    if case_insensitive {
        builder.case_insensitive(true);
    }
    // For no_unicode, disable unicode? We can set unicode false?
    if opts.no_unicode {
        // regex crate's unicode flag
        // builder.unicode(false) ? But bytes regex uses different.
        // We'll attempt to set? RegexBuilder for bytes doesn't have unicode flag? It does have unicode.
        // For simplicity ignore.
    }
    if opts.multiline {
        // When multiline enabled, allow . to match newline if multiline_dotall, else ^ $ handle?
        // For bytes regex, dot matches any byte except newline by default unless dot_matches_new_line
        if opts.multiline_dotall {
            builder.dot_matches_new_line(true);
        }
        // Also enable multi_line? Actually multiline mode means restriction that match cannot include line terminator is lifted. In rust regex, that is always allowed? The . not matching newline is separate.
        // We'll just enable dot_matches_new_line if dotall, else not.
        // Also need to allow ^ and $ to match line boundaries? In multiline mode, they should match across lines?
        builder.multi_line(true);
    }
    if opts.crlf {
        // CRLF line terminators: makes $ match before \r\n? We can ignore for now.
    }
    // Size limits ignored
    // Check engine: if engine is pcre2 or pcre2 flag set, error
    if opts.pcre2 || opts.engine.as_deref() == Some("pcre2") {
        return Err("PCRE2 is not available in this build of ripgrep".to_string());
    }
    // auto-hybrid-regex deprecated, but if set, we still try default engine
    // Build
    let re = builder.build().map_err(|e| format!("regex error: {}", e))?;
    Ok(re)
}

#[derive(Debug)]
struct SearchResult {
    file_path: PathBuf,
    matches: Vec<LineMatch>,
    is_binary: Option<usize>, // Some(offset) if binary detected
    has_match: bool,
}

#[derive(Debug)]
struct LineMatch {
    line_number: usize,
    column: Option<usize>, // 1-based byte offset of first match
    byte_offset: usize, // absolute byte offset of line start
    line_content: Vec<u8>, // raw line bytes
    match_ranges: Vec<(usize, usize)>, // relative to line_content
    is_context: bool, // for context lines
}

fn decompress_if_needed(path: &Path, data: Vec<u8>, opts: &Options) -> Vec<u8> {
    if !opts.search_zip {
        return data;
    }
    // Try to detect gzip, bzip2, xz, etc by extension
    let ext = path.extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase();
    let file_name = path.file_name().and_then(|n| n.to_str()).unwrap_or("").to_lowercase();
    // For simplicity, check magic bytes
    if data.starts_with(&[0x1f, 0x8b]) {
        // gzip
        // Use flate2? But we don't have flate2 crate dependency? Check cargo registry: flate2 exists, but we didn't include. We can attempt to use external command gzip -dc? But original rg shells out to gzip etc.
        // For our implementation, we will try to use std::process to call gzip -cd
        // If fails, return original data
        if let Ok(output) = process::Command::new("gzip").arg("-dc").arg(path).output() {
            if output.status.success() {
                return output.stdout;
            }
        }
        // try with data via stdin
        if let Ok(mut child) = process::Command::new("gzip").arg("-dc").stdin(process::Stdio::piped()).stdout(process::Stdio::piped()).spawn() {
            if let Some(mut stdin) = child.stdin.take() {
                let _ = stdin.write_all(&data);
            }
            if let Ok(output) = child.wait_with_output() {
                if output.status.success() {
                    return output.stdout;
                }
            }
        }
        return data;
    }
    // For other compressions, try using appropriate command
    // We'll check extension
    if file_name.ends_with(".gz") || file_name.ends_with(".tgz") {
        // try gzip
        if let Ok(output) = process::Command::new("gzip").arg("-dc").arg(path).output() {
            if output.status.success() { return output.stdout; }
        }
    }
    if file_name.ends_with(".bz2") || file_name.ends_with(".tbz2") {
        if let Ok(output) = process::Command::new("bzip2").arg("-dc").arg(path).output() {
            if output.status.success() { return output.stdout; }
        }
    }
    if file_name.ends_with(".xz") || file_name.ends_with(".txz") {
        if let Ok(output) = process::Command::new("xz").arg("-dc").arg(path).output() {
            if output.status.success() { return output.stdout; }
        }
    }
    if file_name.ends_with(".zst") || file_name.ends_with(".zstd") {
        if let Ok(output) = process::Command::new("zstd").arg("-dc").arg(path).output() {
            if output.status.success() { return output.stdout; }
        }
        if let Ok(output) = process::Command::new("pzstd").arg("-dc").arg(path).output() {
            if output.status.success() { return output.stdout; }
        }
    }
    if file_name.ends_with(".lz4") {
        if let Ok(output) = process::Command::new("lz4").arg("-dc").arg(path).output() {
            if output.status.success() { return output.stdout; }
        }
    }
    // Brotli: .br
    if file_name.ends_with(".br") {
        if let Ok(output) = process::Command::new("brotli").arg("-dc").arg(path).output() {
            if output.status.success() { return output.stdout; }
        }
    }
    data
}

fn run_preprocessor(path: &Path, opts: &Options) -> Option<Vec<u8>> {
    let pre_cmd = opts.pre.as_ref()?;
    if pre_cmd.is_empty() { return None; }
    // Check pre_glob filter
    if !opts.pre_glob.is_empty() {
        let matched = opts.pre_glob.iter().any(|glob_pat| {
            // simple glob matching using globset
            // For simplicity, use glob crate matching? We'll use globset builder per check
            let mut builder = GlobSetBuilder::new();
            if let Ok(glob) = Glob::new(glob_pat) {
                builder.add(glob);
                if let Ok(set) = builder.build() {
                    return set.is_match(path);
                }
            }
            false
        });
        if !matched {
            return None;
        }
    }
    // Run pre command with path as arg
    // The command may be a shell command? According to rg, it's a command to execute with path as arg.
    // We'll split by whitespace? For simplicity, if command contains spaces, we use shell -c
    // But rg expects COMMAND to be a program path or available in PATH, and passes path as arg.
    // So we should execute COMMAND with arg path.
    // If COMMAND contains spaces, treat as shell?
    // We'll attempt to execute via shell: "$COMMAND" "$PATH"
    let output = if pre_cmd.contains(' ') {
        // use shell
        process::Command::new("sh").arg("-c").arg(format!("{} \"$1\"", pre_cmd)).arg("sh").arg(path).output()
    } else {
        process::Command::new(pre_cmd).arg(path).output()
    };
    if let Ok(out) = output {
        if out.status.success() {
            return Some(out.stdout);
        }
    }
    None
}

fn search_file(path: &Path, regex: &Regex, opts: &Options, is_explicit: bool) -> io::Result<SearchResult> {
    // Read file
    let mut data: Vec<u8> = Vec::new();
    // Check preprocessor
    if let Some(pre_data) = run_preprocessor(path, opts) {
        data = pre_data;
    } else {
        // Read file content
        let file = File::open(path);
        if let Err(e) = file {
            if opts.no_messages {
                return Ok(SearchResult { file_path: path.to_path_buf(), matches: Vec::new(), is_binary: None, has_match: false });
            } else {
                // Will be reported as error elsewhere
                return Err(e);
            }
        }
        let mut file = file.unwrap();
        file.read_to_end(&mut data)?;
        // decompress if needed
        if opts.search_zip {
            data = decompress_if_needed(path, data, opts);
        }
    }

    // Check max_filesize
    if let Some(max) = opts.max_filesize {
        if data.len() as u64 > max {
            return Ok(SearchResult { file_path: path.to_path_buf(), matches: Vec::new(), is_binary: None, has_match: false });
        }
    }

    // Binary detection
    let binary_offset = is_binary(&data);
    let is_binary_file = binary_offset.is_some();

    // Handle binary modes
    if is_binary_file && !opts.text {
        if opts.binary {
            // binary mode: search until match or EOF, if match, print binary file matches message?
            // For our SearchResult, we will still search but mark as binary.
        } else {
            // For explicit file: should go to binary mode (print binary file matches if match found)?
            // For recursive dir search: skip file entirely (no matches) unless we want to print binary file matches?
            // According to earlier debug, for dir search, binary files are ignored (skipped) regardless of match.
            // So if !is_explicit and !opts.binary and !opts.text, skip file.
            if !is_explicit {
                // Skip
                return Ok(SearchResult { file_path: path.to_path_buf(), matches: Vec::new(), is_binary: binary_offset, has_match: false });
            }
            // else is explicit, treat as binary mode: continue searching, but later we will output binary file matches message if has match
        }
    }

    // If null_data, split by \0, else by \n
    // For multiline, search whole data
    let mut matches = Vec::new();

    if opts.multiline {
        // Search entire data as one string
        // But we still need line numbers? Multiline: line numbers are still based on line boundaries? For simplicity, we will find matches and compute line numbers by counting \n before match.
        // Also need to handle context? Context for multiline is tricky, we will not implement fully, just return matches with line numbers.

        // Search
        for mat in regex.find_iter(&data) {
            let start = mat.start();
            let end = mat.end();
            // Find line number for start
            let line_num = data[..start].iter().filter(|&&b| b == b'\n').count() + 1;
            // Find byte offset of line start
            let line_start = data[..start].iter().rposition(|&b| b == b'\n').map(|p| p+1).unwrap_or(0);
            let line_end = data[start..].iter().position(|&b| b == b'\n').map(|p| start + p + 1).unwrap_or(data.len());
            // For multiline, the match may span multiple lines, include them
            let match_end_line = data[..end].iter().filter(|&&b| b == b'\n').count() + 1;
            // For simplicity, take line_content as from line_start to line_end (first line of match)
            // But if match spans multiple lines, we should include all lines up to match_end
            let content_end = data[..end].iter().rposition(|&b| b == b'\n').map(|p| if p < end { data[..p].iter().rposition(|&b| b == b'\n').map(|_| p+1).unwrap_or(0) } else { end }).unwrap_or(end);
            // Simpler: content is data[line_start..line_end] but for multiline we need more?
            // We'll take from line_start to next newline after end? Actually to include whole match.
            let mut actual_line_end = line_end;
            if end > line_end {
                // match spans beyond first line, extend to include up to end's line
                if let Some(pos) = data[end..].iter().position(|&b| b == b'\n') {
                    actual_line_end = end + pos + 1;
                } else {
                    actual_line_end = data.len();
                }
                // Also extend start remains line_start
            }
            let line_content = data[line_start..actual_line_end].to_vec();
            let rel_start = start - line_start;
            let rel_end = (end - line_start).min(line_content.len());

            matches.push(LineMatch {
                line_number: line_num,
                column: Some(rel_start+1),
                byte_offset: line_start,
                line_content,
                match_ranges: vec![(rel_start, rel_end)],
                is_context: false,
            });
            if let Some(max) = opts.max_count {
                if matches.len() >= max { break; }
            }
            if opts.stop_on_nonmatch {
                // Not relevant for multiline?
            }
        }
    } else {
        // line by line
        let separator = if opts.null_data { b'\0' } else { b'\n' };
        let mut line_start_offset = 0usize;
        let mut line_number = 1usize;
        let mut buf_start = 0usize;
        let mut had_nonmatch_after_match = false;
        let mut found_match = false;

        while buf_start <= data.len() {
            let line_end = if let Some(pos) = data[buf_start..].iter().position(|&b| b == separator) {
                buf_start + pos
            } else {
                data.len()
            };
            let line_slice = &data[buf_start..line_end];
            // For crlf, strip trailing \r
            let line_for_search = if opts.crlf {
                if line_slice.ends_with(&[b'\r']) {
                    &line_slice[..line_slice.len()-1]
                } else { line_slice }
            } else { line_slice };

            let is_match = if opts.fixed_strings && opts.patterns.len()==1 && regex.as_str()==".*" {
                // empty pattern case: matches all
                true
            } else {
                regex.is_match(line_for_search)
            };

            let mut actual_is_match = is_match;
            if opts.invert_match {
                actual_is_match = !is_match;
            }

            if actual_is_match {
                found_match = true;
                // Find all matches in line for only-matching etc
                let match_ranges: Vec<(usize, usize)> = if opts.invert_match {
                    Vec::new()
                } else {
                    regex.find_iter(line_for_search).map(|m| (m.start(), m.end())).collect()
                };

                // For column, first match start
                let col = if !match_ranges.is_empty() {
                    Some(match_ranges[0].0 + 1)
                } else {
                    None
                };

                matches.push(LineMatch {
                    line_number,
                    column: col,
                    byte_offset: line_start_offset,
                    line_content: line_slice.to_vec(), // raw line
                    match_ranges,
                    is_context: false,
                });

                if let Some(max) = opts.max_count {
                    if matches.len() >= max { break; }
                }
                if opts.passthru {
                    // passthru prints both matching and non-matching, but our matches list currently only includes matching lines.
                    // For passthru logic, we need to handle printing later: we will print all lines.
                }
            } else {
                // non-match
                if opts.stop_on_nonmatch && found_match {
                    had_nonmatch_after_match = true;
                    break;
                }
                if opts.passthru {
                    matches.push(LineMatch {
                        line_number,
                        column: None,
                        byte_offset: line_start_offset,
                        line_content: line_slice.to_vec(),
                        match_ranges: Vec::new(),
                        is_context: false,
                    });
                }
            }

            // Move to next line
            line_number += 1;
            line_start_offset = line_end + 1; // +1 for separator
            buf_start = line_end + 1;
            if buf_start > data.len() { break; }
        }
    }

    Ok(SearchResult {
        file_path: path.to_path_buf(),
        matches,
        is_binary: binary_offset,
        has_match: !matches.is_empty(),
    })
}

fn search_stdin(regex: &Regex, opts: &Options) -> SearchResult {
    let stdin = io::stdin();
    let mut data = Vec::new();
    let _ = stdin.lock().read_to_end(&mut data);
    if opts.search_zip {
        data = decompress_if_needed(Path::new("stdin"), data, opts);
    }
    let binary_offset = is_binary(&data);
    let is_binary_file = binary_offset.is_some();
    if is_binary_file && !opts.text && !opts.binary {
        // For stdin, treat as binary? According to rg, binary detection for stdin?
        // We'll just search anyway? For simplicity, if binary and no text, skip? But stdin binary should be treated?
        // We'll treat as text for stdin to allow searching.
    }

    let mut matches = Vec::new();
    if opts.multiline {
        for mat in regex.find_iter(&data) {
            let start = mat.start();
            let line_num = data[..start].iter().filter(|&&b| b == b'\n').count() + 1;
            let line_start = data[..start].iter().rposition(|&b| b == b'\n').map(|p| p+1).unwrap_or(0);
            let line_end = data[start..].iter().position(|&b| b == b'\n').map(|p| start + p + 1).unwrap_or(data.len());
            let line_content = data[line_start..line_end].to_vec();
            let rel_start = start - line_start;
            let rel_end = (mat.end() - line_start).min(line_content.len());
            matches.push(LineMatch {
                line_number: line_num,
                column: Some(rel_start+1),
                byte_offset: line_start,
                line_content,
                match_ranges: vec![(rel_start, rel_end)],
                is_context: false,
            });
        }
    } else {
        let separator = if opts.null_data { b'\0' } else { b'\n' };
        let mut line_start_offset = 0usize;
        let mut line_number = 1usize;
        let mut buf_start = 0usize;
        while buf_start <= data.len() {
            let line_end = if let Some(pos) = data[buf_start..].iter().position(|&b| b == separator) {
                buf_start + pos
            } else {
                data.len()
            };
            let line_slice = &data[buf_start..line_end];
            let line_for_search = if opts.crlf {
                if line_slice.ends_with(&[b'\r']) { &line_slice[..line_slice.len()-1] } else { line_slice }
            } else { line_slice };

            let is_match = regex.is_match(line_for_search);
            let actual = if opts.invert_match { !is_match } else { is_match };
            if actual {
                let match_ranges = if opts.invert_match { Vec::new() } else { regex.find_iter(line_for_search).map(|m| (m.start(), m.end())).collect() };
                let col = match_ranges.get(0).map(|(s,_)| s+1);
                matches.push(LineMatch {
                    line_number,
                    column: col,
                    byte_offset: line_start_offset,
                    line_content: line_slice.to_vec(),
                    match_ranges,
                    is_context: false,
                });
            } else if opts.passthru {
                matches.push(LineMatch {
                    line_number,
                    column: None,
                    byte_offset: line_start_offset,
                    line_content: line_slice.to_vec(),
                    match_ranges: Vec::new(),
                    is_context: false,
                });
            }
            line_number += 1;
            line_start_offset = line_end + 1;
            buf_start = line_end + 1;
            if buf_start > data.len() { break; }
        }
    }
    SearchResult { file_path: PathBuf::from("stdin"), matches, is_binary: binary_offset, has_match: !matches.is_empty() }
}

fn should_use_color(opts: &Options) -> bool {
    match opts.color.as_str() {
        "never" => false,
        "always" => true,
        "ansi" => true,
        "auto" => {
            // auto: use colors if stdout is tty and TERM not dumb and NO_COLOR not set
            if env::var("NO_COLOR").is_ok() { return false; }
            if let Ok(term) = env::var("TERM") {
                if term == "dumb" { return false; }
            }
            // also check if pretty flag: pretty implies color always?
            if opts.pretty { return true; }
            if opts.vimgrep || opts.json { return false; }
            io::stdout().is_terminal()
        },
        _ => false,
    }
}

fn colorize_match(line: &[u8], ranges: &[(usize, usize)], use_color: bool) -> Vec<u8> {
    if !use_color || ranges.is_empty() {
        return line.to_vec();
    }
    let mut out = Vec::new();
    let mut last = 0;
    for (s,e) in ranges {
        if *s > last {
            out.extend_from_slice(&line[last..*s]);
        }
        // match color: \x1b[0m\x1b[1m\x1b[31m + match + \x1b[0m
        out.extend_from_slice(b"\x1b[0m\x1b[1m\x1b[31m");
        out.extend_from_slice(&line[*s..*e]);
        out.extend_from_slice(b"\x1b[0m");
        last = *e;
    }
    if last < line.len() {
        out.extend_from_slice(&line[last..]);
    }
    out
}

