fn build_walk_builder(path: &Path, opts: &Options) -> WalkBuilder {
    let mut builder = WalkBuilder::new(path);
    builder.hidden(!opts.hidden && opts.unrestricted < 2);
    builder.ignore(!opts.no_ignore && opts.unrestricted < 1);
    builder.git_ignore(!opts.no_ignore_vcs && opts.unrestricted < 1);
    builder.git_global(!opts.no_ignore_global && opts.unrestricted < 1);
    builder.git_exclude(!opts.no_ignore_exclude && opts.unrestricted < 1);
    builder.parents(!opts.no_ignore_parent && opts.unrestricted < 1);
    builder.require_git(!opts.no_require_git);
    builder.follow_links(opts.follow);
    builder.max_depth(opts.max_depth);
    builder.same_file_system(opts.one_file_system);
    // max_filesize handled manually
    // For ignore files
    if !opts.no_ignore_files {
        for ignore_file in &opts.ignore_files {
            // Add ignore file via override? The ignore crate has add_ignore_file?
            // WalkBuilder has add_ignore_file? Actually it has add_custom_ignore_filename? No.
            // For simplicity, we will handle ignore files manually via filter? But we can use builder.add_ignore_file?
            // Check ignore crate API: WalkBuilder has add_ignore_file? I think it does.
            // We'll attempt: builder.add_ignore_file(ignore_file)
            // Let's see if method exists: In ignore 0.4, WalkBuilder has add_ignore_file?
            // According to docs, there is add_ignore_file method that takes path.
            // We'll try.
            builder.add_ignore_file(ignore_file);
        }
    }
    // For globs: need to add overrides
    if !opts.globs.is_empty() {
        let mut override_builder = globset::GlobSetBuilder::new();
        // Actually ignore's override via OverrideBuilder
        // For simplicity, we will not use override builder here, but filter files manually in file_matches_filters
        // So walk builder will still walk all files, filtering later.
    }
    // For types: also filter manually
    builder
}

fn file_matches_filters(path: &Path, opts: &Options) -> bool {
    // Check max_filesize already handled elsewhere

    // Check globs
    if !opts.globs.is_empty() {
        // Globs are matched against path
        // According to rg, globs are matched against file path relative to search root? For simplicity, match against file name and full path?
        // We'll implement: each glob is matched, if glob starts with '!' it's exclusion, else inclusion.
        // Multiple globs: later globs take precedence.
        // For our implementation, we will process globs in order, keeping an inclusion state.
        // Initially, if there is any inclusion glob (non-negated), then file must match at least one inclusion to be included? Actually rg's -g semantics: -g '*.txt' means only search files matching glob. If you give -g '!*.txt', exclude those.
        // So logic: if globs contain inclusion patterns, file must match at least one inclusion. If it matches exclusion later, excluded.
        // Simplistic: start with None meaning no decision. Process each glob:
        // If glob starts with '!' => if matches, then exclude (set to false)
        // Else => if matches, include (set to true)
        // At end, if there was any inclusion glob, file must be included (true) to pass, else if only exclusions, pass unless excluded.
        // Also need to handle case insensitivity.

        let mut included: Option<bool> = None;
        let mut has_inclusion = false;
        for (pat, case_insensitive) in &opts.globs {
            let is_negated = pat.starts_with('!');
            let actual_pat = if is_negated { &pat[1..] } else { pat.as_str() };
            if !is_negated { has_inclusion = true; }
            // Build glob
            let mut glob_builder = Glob::new(actual_pat);
            // For case insensitive, we need to use GlobBuilder?
            // Glob crate has case_insensitive option via GlobBuilder
            let glob_result = if *case_insensitive {
                globset::GlobBuilder::new(actual_pat).case_insensitive(true).build()
            } else {
                Glob::new(actual_pat)
            };
            if let Ok(glob) = glob_result {
                let matcher = glob.compile_matcher();
                // Match against file path and file name? rg matches against path?
                // We'll match against file name and also full path string
                let path_str = path.to_string_lossy();
                let file_name = path.file_name().and_then(|n| n.to_str()).unwrap_or("");
                let matched = matcher.is_match(path) || matcher.is_match(file_name) || matcher.is_match(path_str.as_ref());
                if matched {
                    if is_negated {
                        included = Some(false);
                    } else {
                        included = Some(true);
                    }
                }
            }
        }
        if has_inclusion {
            if included != Some(true) {
                return false;
            }
        } else {
            if included == Some(false) {
                return false;
            }
        }
    }

    // Check type filters
    if !opts.type_filter.is_empty() || !opts.type_not_filter.is_empty() || !opts.type_add.is_empty() || !opts.type_clear.is_empty() {
        // Build type map
        let mut type_map = parse_builtin_types();
        // Apply type_clear
        for clear in &opts.type_clear {
            type_map.remove(clear);
        }
        // Apply type_add
        for (name, glob_str) in &opts.type_add {
            // glob_str may be like "*.ext" or "include:other"
            // If it starts with "include:", then include other type's globs
            if glob_str.starts_with("include:") {
                let other = &glob_str["include:".len()..];
                if let Some(other_globs) = type_map.get(other).cloned() {
                    type_map.entry(name.clone()).or_insert(Vec::new()).extend(other_globs);
                }
            } else {
                type_map.entry(name.clone()).or_insert(Vec::new()).push(glob_str.clone());
            }
        }

        // If type_filter specified, file must match at least one of those types
        if !opts.type_filter.is_empty() {
            let mut matches_any = false;
            for t in &opts.type_filter {
                if let Some(globs) = type_map.get(t) {
                    for g in globs {
                        if let Ok(glob) = Glob::new(g) {
                            if glob.compile_matcher().is_match(path) {
                                matches_any = true;
                                break;
                            }
                            // Also match file name
                            if let Some(fname) = path.file_name().and_then(|n| n.to_str()) {
                                if glob.compile_matcher().is_match(fname) {
                                    matches_any = true;
                                    break;
                                }
                            }
                        }
                    }
                }
                if matches_any { break; }
            }
            if !matches_any { return false; }
        }
        // type_not
        if !opts.type_not_filter.is_empty() {
            for t in &opts.type_not_filter {
                if let Some(globs) = type_map.get(t) {
                    for g in globs {
                        if let Ok(glob) = Glob::new(g) {
                            if glob.compile_matcher().is_match(path) {
                                return false;
                            }
                            if let Some(fname) = path.file_name().and_then(|n| n.to_str()) {
                                if glob.compile_matcher().is_match(fname) {
                                    return false;
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    true
}
