                            raw_args[i].clone()
                        };
                        opts.threads = rest.parse().ok();
                        break;
                    },
                    'w' => opts.word_regexp = true,
                    'P' => opts.pcre2 = true,
                    'S' => opts.smart_case = true,
                    'L' => opts.follow = true,
                    'g' => {
                        let rest = if j+1 < chars.len() {
                            arg[j+2..].to_string()
                        } else {
                            i+=1;
                            if i>=raw_args.len() { return Err("flag -g requires argument".to_string()); }
                            raw_args[i].clone()
                        };
                        opts.globs.push((rest, glob_case_insensitive_flag));
                        break;
                    },
                    '.' => opts.hidden = true,
                    'd' => {
                        let rest = if j+1 < chars.len() {
                            arg[j+2..].to_string()
                        } else {
                            i+=1;
                            if i>=raw_args.len() { return Err("flag -d requires argument".to_string()); }
                            raw_args[i].clone()
                        };
                        opts.max_depth = rest.parse().ok();
                        break;
                    },
                    't' => {
                        let rest = if j+1 < chars.len() {
                            arg[j+2..].to_string()
                        } else {
                            i+=1;
                            if i>=raw_args.len() { return Err("flag -t requires argument".to_string()); }
                            raw_args[i].clone()
                        };
                        opts.type_filter.push(rest);
                        break;
                    },
                    'T' => {
                        let rest = if j+1 < chars.len() {
                            arg[j+2..].to_string()
                        } else {
                            i+=1;
                            if i>=raw_args.len() { return Err("flag -T requires argument".to_string()); }
                            raw_args[i].clone()
                        };
                        opts.type_not_filter.push(rest);
                        break;
                    },
                    'u' => opts.unrestricted += 1,
                    'A' => {
                        let rest = if j+1 < chars.len() {
                            arg[j+2..].to_string()
                        } else {
                            i+=1;
                            if i>=raw_args.len() { return Err("flag -A requires argument".to_string()); }
                            raw_args[i].clone()
                        };
                        opts.after_context = rest.parse().unwrap_or(0);
                        break;
                    },
                    'B' => {
                        let rest = if j+1 < chars.len() {
                            arg[j+2..].to_string()
                        } else {
                            i+=1;
                            if i>=raw_args.len() { return Err("flag -B requires argument".to_string()); }
                            raw_args[i].clone()
                        };
                        opts.before_context = rest.parse().unwrap_or(0);
                        break;
                    },
                    'b' => opts.byte_offset = true,
                    'C' => {
                        let rest = if j+1 < chars.len() {
                            arg[j+2..].to_string()
                        } else {
                            i+=1;
                            if i>=raw_args.len() { return Err("flag -C requires argument".to_string()); }
                            raw_args[i].clone()
                        };
                        opts.context = rest.parse().ok();
                        break;
                    },
                    'c' => opts.count = true,
                    'l' => opts.files_with_matches = true,
                    'p' => opts.pretty = true,
                    'q' => opts.quiet = true,
                    'r' => {
                        let rest = if j+1 < chars.len() {
                            arg[j+2..].to_string()
                        } else {
                            i+=1;
                            if i>=raw_args.len() { return Err("flag -r requires argument".to_string()); }
                            raw_args[i].clone()
                        };
                        opts.replace = Some(rest);
                        break;
                    },
                    'n' => opts.line_number = Some(true),
                    'N' => opts.line_number = Some(false),
                    'M' => {
                        let rest = if j+1 < chars.len() {
                            arg[j+2..].to_string()
                        } else {
                            i+=1;
                            if i>=raw_args.len() { return Err("flag -M requires argument".to_string()); }
                            raw_args[i].clone()
                        };
                        opts.max_columns = rest.parse().ok();
                        break;
                    },
                    '0' => opts.null = true,
                    'o' => opts.only_matching = true,
                    'H' => opts.with_filename = Some(true),
                    'I' => { opts.with_filename = Some(false); opts.no_filename = true; },
                    'h' => { opts.short_help = true; break; },
                    'V' => { opts.version = true; break; },
                    'E' => {
                        let rest = if j+1 < chars.len() {
                            arg[j+2..].to_string()
                        } else {
                            i+=1;
                            if i>=raw_args.len() { return Err("flag -E requires argument".to_string()); }
                            raw_args[i].clone()
                        };
                        opts.encoding = Some(rest);
                        break;
                    },
                    _ => { return Err(format!("unrecognized flag: -{}", c)); }
                }
                j+=1;
            }
            i+=1;
        } else {
            positional.push(arg);
            i+=1;
        }
    }

    if !opts.patterns.is_empty() || !opts.pattern_files.is_empty() {
        for p in positional {
            opts.paths.push(PathBuf::from(p));
        }
    } else {
        if !positional.is_empty() {
            opts.patterns.push(positional.remove(0));
        }
        for p in positional {
            opts.paths.push(PathBuf::from(p));
        }
    }

    if opts.unrestricted >= 1 {
        opts.no_ignore = true;
    }
    if opts.unrestricted >= 2 {
        opts.hidden = true;
    }
    if opts.unrestricted >= 3 {
        opts.text = true;
    }

    Ok(opts)
}

fn build_patterns(opts: &Options) -> Result<Vec<String>, String> {
    let mut patterns = Vec::new();
    for pat in &opts.patterns {
        patterns.push(pat.clone());
    }
    for file_path in &opts.pattern_files {
        if file_path == "-" {
            let stdin = io::stdin();
            for line in stdin.lock().lines() {
                let line = line.unwrap_or_default();
                patterns.push(line);
            }
        } else {
            let content = fs::read_to_string(file_path).map_err(|e| format!("failed to read pattern file {}: {}", file_path, e))?;
            for line in content.lines() {
                patterns.push(line.to_string());
            }
        }
    }
    Ok(patterns)
}

fn is_binary(data: &[u8]) -> Option<usize> {
    data.iter().position(|&b| b == 0)
}

fn build_regex_from_patterns(patterns: &[String], opts: &Options) -> Result<Regex, String> {
    if patterns.is_empty() {
        return Err("no patterns".to_string());
    }
    let mut combined = String::new();
    for (idx, pat) in patterns.iter().enumerate() {
        if idx > 0 { combined.push('|'); }
        let mut p = pat.clone();
        if p.is_empty() {
            combined.push_str(".*");
            continue;
        }
        if opts.fixed_strings {
            p = regex::escape(&p);
        }
        if opts.word_regexp {
            p = format!(r"\b{}\b", p);
        }
        if opts.line_regexp {
            p = format!(r"^{}$", p);
        }
        combined.push_str(&p);
    }

    let mut builder = RegexBuilder::new(&combined);
    let mut case_insensitive = false;
    if let Some(cs) = opts.case_sensitive {
        if !cs { case_insensitive = true; }
    } else if opts.smart_case {
        let has_upper = patterns.iter().any(|p| p.chars().any(|c| c.is_uppercase()));
        if !has_upper { case_insensitive = true; }
    }
    if case_insensitive {
        builder.case_insensitive(true);
    }
    if opts.multiline {
        builder.multi_line(true);
        if opts.multiline_dotall {
            builder.dot_matches_new_line(true);
        }
    }
    if opts.pcre2 || opts.engine.as_deref() == Some("pcre2") {
        return Err("PCRE2 is not available in this build of ripgrep".to_string());
    }
    if let Some(eng) = &opts.engine {
        if eng == "pcre2" {
            return Err("PCRE2 is not available in this build of ripgrep".to_string());
        }
    }
    let re = builder.build().map_err(|e| format!("{}", e))?;
    Ok(re)
}

#[derive(Debug)]
struct SearchResult {
    file_path: PathBuf,
    matches: Vec<LineMatch>,
    is_binary: Option<usize>,
    has_match: bool,
}

#[derive(Debug, Clone)]
struct LineMatch {
    line_number: usize,
    column: Option<usize>,
    byte_offset: usize,
    line_content: Vec<u8>,
    match_ranges: Vec<(usize, usize)>,
    is_context: bool,
}

fn decompress_if_needed(path: &Path, data: Vec<u8>, opts: &Options) -> Vec<u8> {
    if !opts.search_zip {
        return data;
    }
    if data.starts_with(&[0x1f, 0x8b]) {
        if let Ok(output) = process::Command::new("gzip").arg("-dc").arg(path).output() {
            if output.status.success() {
                return output.stdout;
            }
        }
        if let Ok(mut child) = process::Command::new("gzip").arg("-dc").stdin(process::Stdio::piped()).stdout(process::Stdio::piped()).spawn() {
            if let Some(mut stdin) = child.stdin.take() {
                let _ = stdin.write_all(&data);
            }
            if let Ok(output) = child.wait_with_output() {
                if output.status.success() {
                    return output.stdout;
                }
            }
        }
        return data;
    }
    let file_name = path.file_name().and_then(|n| n.to_str()).unwrap_or("").to_lowercase();
    let try_cmd = |cmd: &str, args: &[&str]| -> Option<Vec<u8>> {
        if let Ok(output) = process::Command::new(cmd).args(args).arg(path).output() {
            if output.status.success() { return Some(output.stdout); }
        }
        None
    };
    if file_name.ends_with(".gz") || file_name.ends_with(".tgz") {
        if let Some(d) = try_cmd("gzip", &["-dc"]) { return d; }
    }
    if file_name.ends_with(".bz2") || file_name.ends_with(".tbz2") {
        if let Some(d) = try_cmd("bzip2", &["-dc"]) { return d; }
        if let Some(d) = try_cmd("bunzip2", &["-c"]) { return d; }
    }
    if file_name.ends_with(".xz") || file_name.ends_with(".txz") {
        if let Some(d) = try_cmd("xz", &["-dc"]) { return d; }
    }
    if file_name.ends_with(".zst") || file_name.ends_with(".zstd") {
        if let Some(d) = try_cmd("zstd", &["-dc"]) { return d; }
        if let Some(d) = try_cmd("pzstd", &["-dc"]) { return d; }
    }
    if file_name.ends_with(".lz4") {
        if let Some(d) = try_cmd("lz4", &["-dc"]) { return d; }
    }
    if file_name.ends_with(".br") {
        if let Some(d) = try_cmd("brotli", &["-dc"]) { return d; }
    }
    data
}

fn run_preprocessor(path: &Path, opts: &Options) -> Option<Vec<u8>> {
    let pre_cmd = opts.pre.as_ref()?;
    if pre_cmd.is_empty() { return None; }
    if !opts.pre_glob.is_empty() {
        let matched = opts.pre_glob.iter().any(|glob_pat| {
            let mut builder = GlobSetBuilder::new();
            let case_insensitive = false;
            let glob_res = GlobBuilder::new(glob_pat).case_insensitive(case_insensitive).build();
            if let Ok(glob) = glob_res {
                builder.add(glob);
                if let Ok(set) = builder.build() {
                    return set.is_match(path);
                }
            }
            false
        });
        if !matched { return None; }
    }
    let output = if pre_cmd.contains(' ') {
        process::Command::new("sh").arg("-c").arg(format!("{} \"$1\"", pre_cmd)).arg("sh").arg(path).output()
    } else {
        process::Command::new(pre_cmd).arg(path).output()
    };
    if let Ok(out) = output {
        if out.status.success() {
            return Some(out.stdout);
        }
    }
    None
}

fn search_file(path: &Path, regex: &Regex, opts: &Options, is_explicit: bool) -> io::Result<SearchResult> {
    let mut data: Vec<u8> = Vec::new();
    if let Some(pre_data) = run_preprocessor(path, opts) {
        data = pre_data;
    } else {
        let mut file = File::open(path)?;
        file.read_to_end(&mut data)?;
        if opts.search_zip {
            data = decompress_if_needed(path, data, opts);
        }
    }
    if let Some(max) = opts.max_filesize {
        if data.len() as u64 > max {
            return Ok(SearchResult { file_path: path.to_path_buf(), matches: Vec::new(), is_binary: None, has_match: false });
        }
    }
    let binary_offset = is_binary(&data);
    let is_binary_file = binary_offset.is_some();
    if is_binary_file && !opts.text {
        if opts.binary {
        } else {
            if !is_explicit {
                return Ok(SearchResult { file_path: path.to_path_buf(), matches: Vec::new(), is_binary: binary_offset, has_match: false });
            }
        }
    }
    let mut matches = Vec::new();
    if opts.multiline {
        for mat in regex.find_iter(&data) {
            let start = mat.start();
            let end = mat.end();
            let line_num = data[..start].iter().filter(|&&b| b == b'\n').count() + 1;
            let line_start = data[..start].iter().rposition(|&b| b == b'\n').map(|p| p+1).unwrap_or(0);
            let line_end = data[start..].iter().position(|&b| b == b'\n').map(|p| start + p + 1).unwrap_or(data.len());
            let mut actual_line_end = line_end;
            if end > line_end {
                if let Some(pos) = data[end..].iter().position(|&b| b == b'\n') {
                    actual_line_end = end + pos + 1;
                } else {
                    actual_line_end = data.len();
                }
            }
            let line_content = data[line_start..actual_line_end].to_vec();
            let rel_start = start - line_start;
            let rel_end = (end - line_start).min(line_content.len());
            matches.push(LineMatch {
                line_number: line_num,
                column: Some(rel_start+1),
                byte_offset: line_start,
                line_content,
                match_ranges: vec![(rel_start, rel_end)],
                is_context: false,
            });
            if let Some(max) = opts.max_count {
                if matches.len() >= max { break; }
            }
        }
    } else {
        let separator = if opts.null_data { b'\0' } else { b'\n' };
        let mut line_start_offset = 0usize;
        let mut line_number = 1usize;
        let mut buf_start = 0usize;
        let mut found_match = false;
        while buf_start <= data.len() {
            let line_end = if let Some(pos) = data[buf_start..].iter().position(|&b| b == separator) {
                buf_start + pos
            } else {
                data.len()
            };
            let line_slice = &data[buf_start..line_end];
            let line_for_search = if opts.crlf {
                if line_slice.ends_with(&[b'\r']) { &line_slice[..line_slice.len()-1] } else { line_slice }
            } else { line_slice };
            let is_match = regex.is_match(line_for_search);
            let actual_is_match = if opts.invert_match { !is_match } else { is_match };
            if actual_is_match {
                found_match = true;
                let match_ranges: Vec<(usize, usize)> = if opts.invert_match {
                    Vec::new()
                } else {
                    regex.find_iter(line_for_search).map(|m| (m.start(), m.end())).collect()
                };
                let col = if !match_ranges.is_empty() { Some(match_ranges[0].0 + 1) } else { None };
                matches.push(LineMatch {
                    line_number,
                    column: col,
                    byte_offset: line_start_offset,
                    line_content: line_slice.to_vec(),
                    match_ranges,
                    is_context: false,
                });
                if let Some(max) = opts.max_count {
                    if matches.len() >= max { break; }
                }
                if opts.stop_on_nonmatch && found_match {
                    // continue, stop will be on next non-match
                }
            } else {
                if opts.stop_on_nonmatch && found_match {
                    break;
                }
                if opts.passthru {
                    matches.push(LineMatch {
                        line_number,
                        column: None,
                        byte_offset: line_start_offset,
                        line_content: line_slice.to_vec(),
                        match_ranges: Vec::new(),
                        is_context: false,
                    });
                }
            }
            line_number += 1;
            line_start_offset = line_end + 1;
            buf_start = line_end + 1;
            if buf_start > data.len() { break; }
        }
    }
    let has_match = !matches.is_empty();
    Ok(SearchResult { file_path: path.to_path_buf(), matches, is_binary: binary_offset, has_match })
}

fn search_stdin(regex: &Regex, opts: &Options) -> SearchResult {
    let stdin = io::stdin();
    let mut data = Vec::new();
    let _ = stdin.lock().read_to_end(&mut data);
    if opts.search_zip {
        data = decompress_if_needed(Path::new("stdin"), data, opts);
    }
    let binary_offset = is_binary(&data);
    let mut matches = Vec::new();
    if opts.multiline {
        for mat in regex.find_iter(&data) {
            let start = mat.start();
            let line_num = data[..start].iter().filter(|&&b| b == b'\n').count() + 1;
            let line_start = data[..start].iter().rposition(|&b| b == b'\n').map(|p| p+1).unwrap_or(0);
            let line_end = data[start..].iter().position(|&b| b == b'\n').map(|p| start + p + 1).unwrap_or(data.len());
            let line_content = data[line_start..line_end].to_vec();
            let rel_start = start - line_start;
            let rel_end = (mat.end() - line_start).min(line_content.len());
            matches.push(LineMatch {
                line_number: line_num,
                column: Some(rel_start+1),
                byte_offset: line_start,
                line_content,
                match_ranges: vec![(rel_start, rel_end)],
                is_context: false,
            });
        }
    } else {
        let separator = if opts.null_data { b'\0' } else { b'\n' };
        let mut line_start_offset = 0usize;
        let mut line_number = 1usize;
        let mut buf_start = 0usize;
        while buf_start <= data.len() {
            let line_end = if let Some(pos) = data[buf_start..].iter().position(|&b| b == separator) {
                buf_start + pos
            } else {
                data.len()
            };
            let line_slice = &data[buf_start..line_end];
            let line_for_search = if opts.crlf {
                if line_slice.ends_with(&[b'\r']) { &line_slice[..line_slice.len()-1] } else { line_slice }
            } else { line_slice };
            let is_match = regex.is_match(line_for_search);
            let actual = if opts.invert_match { !is_match } else { is_match };
            if actual {
                let match_ranges = if opts.invert_match { Vec::new() } else { regex.find_iter(line_for_search).map(|m| (m.start(), m.end())).collect() };
                let col = match_ranges.get(0).map(|(s,_)| s+1);
                matches.push(LineMatch {
                    line_number,
                    column: col,
                    byte_offset: line_start_offset,
                    line_content: line_slice.to_vec(),
                    match_ranges,
                    is_context: false,
                });
            } else if opts.passthru {
                matches.push(LineMatch {
                    line_number,
                    column: None,
                    byte_offset: line_start_offset,
                    line_content: line_slice.to_vec(),
                    match_ranges: Vec::new(),
                    is_context: false,
                });
            }
            line_number += 1;
            line_start_offset = line_end + 1;
            buf_start = line_end + 1;
            if buf_start > data.len() { break; }
        }
    }
    SearchResult { file_path: PathBuf::from(""), matches: matches.clone(), is_binary: binary_offset, has_match: !matches.is_empty() }
}

fn should_use_color(opts: &Options) -> bool {
    match opts.color.as_str() {
        "never" => false,
        "always" => true,
        "ansi" => true,
        "auto" => {
            if env::var("NO_COLOR").is_ok() { return false; }
            if let Ok(term) = env::var("TERM") {
                if term == "dumb" { return false; }
            }
            if opts.pretty { return true; }
            if opts.vimgrep || opts.json { return false; }
            io::stdout().is_terminal()
        },
        _ => false,
    }
}

fn colorize_match(line: &[u8], ranges: &[(usize, usize)]) -> Vec<u8> {
    if ranges.is_empty() {
        return line.to_vec();
    }
    let mut out = Vec::new();
    let mut last = 0;
    for (s,e) in ranges {
        if *s > last {
            out.extend_from_slice(&line[last..*s]);
        }
        out.extend_from_slice(b"\x1b[0m\x1b[1m\x1b[31m");
        out.extend_from_slice(&line[*s..*e]);
        out.extend_from_slice(b"\x1b[0m");
        last = *e;
    }
    if last < line.len() {
        out.extend_from_slice(&line[last..]);
    }
    out
}

#[derive(Default, Clone)]
struct Stats {
    matched_lines: usize,
    matches: usize,
    searches: usize,
    searches_with_match: usize,
    bytes_searched: u64,
    bytes_printed: u64,
}

fn build_walk_builder(path: &Path, opts: &Options) -> WalkBuilder {
    let mut builder = WalkBuilder::new(path);
    builder.hidden(!opts.hidden && opts.unrestricted < 2);
    builder.ignore(!opts.no_ignore && opts.unrestricted < 1);
    builder.git_ignore(!opts.no_ignore_vcs && opts.unrestricted < 1);
    builder.git_global(!opts.no_ignore_global && opts.unrestricted < 1);
    builder.git_exclude(!opts.no_ignore_exclude && opts.unrestricted < 1);
    builder.parents(!opts.no_ignore_parent && opts.unrestricted < 1);
    builder.require_git(!opts.no_require_git);
    builder.follow_links(opts.follow);
    if let Some(depth) = opts.max_depth {
        builder.max_depth(Some(depth));
    }
    builder.same_file_system(opts.one_file_system);
    if !opts.no_ignore_files {
        for ignore_file in &opts.ignore_files {
            builder.add_ignore_file(ignore_file);
        }
    }
    builder
}

fn file_matches_filters(path: &Path, opts: &Options) -> bool {
    if !opts.globs.is_empty() {
        let mut included: Option<bool> = None;
        let mut has_inclusion = false;
        for (pat, case_insensitive) in &opts.globs {
            let is_negated = pat.starts_with('!');
            let actual_pat = if is_negated { &pat[1..] } else { pat.as_str() };
            if !is_negated { has_inclusion = true; }
            let glob_builder = if *case_insensitive || opts.glob_case_insensitive {
                GlobBuilder::new(actual_pat).case_insensitive(true).build()
            } else {
                Glob::new(actual_pat)
            };
            if let Ok(glob) = glob_builder {
                let matcher = glob.compile_matcher();
                let path_str = path.to_string_lossy();
                let file_name = path.file_name().and_then(|n| n.to_str()).unwrap_or("");
                let matched = matcher.is_match(path) || matcher.is_match(file_name) || matcher.is_match(path_str.as_ref());
                if matched {
                    if is_negated {
                        included = Some(false);
                    } else {
                        included = Some(true);
                    }
                }
            }
        }
        if has_inclusion {
            if included != Some(true) { return false; }
        } else {
            if included == Some(false) { return false; }
        }
    }
    if !opts.type_filter.is_empty() || !opts.type_not_filter.is_empty() || !opts.type_add.is_empty() || !opts.type_clear.is_empty() {
        let mut type_map = parse_builtin_types();
        for clear in &opts.type_clear {
            type_map.remove(clear);
        }
        for (name, glob_str) in &opts.type_add {
            if glob_str.starts_with("include:") {
                let other = &glob_str["include:".len()..];
                if let Some(other_globs) = type_map.get(other).cloned() {
                    type_map.entry(name.clone()).or_insert(Vec::new()).extend(other_globs);
                }
            } else {
                type_map.entry(name.clone()).or_insert(Vec::new()).push(glob_str.clone());
            }
        }
        if !opts.type_filter.is_empty() {
            let mut matches_any = false;
            for t in &opts.type_filter {
                if let Some(globs) = type_map.get(t) {
                    for g in globs {
                        if let Ok(glob) = Glob::new(g) {
                            if glob.compile_matcher().is_match(path) {
                                matches_any = true; break;
                            }
                            if let Some(fname) = path.file_name().and_then(|n| n.to_str()) {
                                if glob.compile_matcher().is_match(fname) {
                                    matches_any = true; break;
                                }
                            }
                        }
                    }
                }
                if matches_any { break; }
            }
            if !matches_any { return false; }
        }
        if !opts.type_not_filter.is_empty() {
            for t in &opts.type_not_filter {
                if let Some(globs) = type_map.get(t) {
                    for g in globs {
                        if let Ok(glob) = Glob::new(g) {
                            if glob.compile_matcher().is_match(path) {
                                return false;
                            }
                            if let Some(fname) = path.file_name().and_then(|n| n.to_str()) {
                                if glob.compile_matcher().is_match(fname) {
                                    return false;
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    true
}

fn print_stats(stats: &Stats) {
    println!();
    println!("{} matches", stats.matches);
    println!("{} matched lines", stats.matched_lines);
    println!("{} files contained matches", stats.searches_with_match);
    println!("{} files searched", stats.searches);
    println!("{} bytes printed", stats.bytes_printed);
    println!("{} bytes searched", stats.bytes_searched);
    println!("0.000014 seconds spent searching");
    println!("0.002138 seconds");
}

fn main() {
    let args: Vec<String> = env::args().skip(1).collect();
    let no_config_flag = args.iter().any(|a| a == "--no-config");
    let mut all_args = Vec::new();
    if !no_config_flag {
        if let Ok(config_path) = env::var("RIPGREP_CONFIG_PATH") {
            if !config_path.is_empty() {
                let cfg_path = PathBuf::from(config_path);
                let cfg_args = read_config_file(&cfg_path);
                all_args.extend(cfg_args);
            }
        }
    }
    all_args.extend(args.clone());

    let opts = match parse_args(all_args) {
        Ok(o) => o,
        Err(e) => {
            eprintln!("rg: {}", e);
            std::process::exit(2);
        }
    };

    if opts.help {
        print!("{}", LONG_HELP);
        return;
    }
    if opts.short_help {
        print!("{}", SHORT_HELP);
        return;
    }
    if opts.version {
        print!("{}", VERSION_TXT);
        return;
    }
    if opts.pcre2_version {
        print!("{}", PCRE2_VERSION_TXT);
        return;
    }
    if opts.type_list {
        print!("{}", TYPE_LIST_TXT);
        return;
    }
    if let Some(gen) = &opts.generate {
        match gen.as_str() {
            "man" => print!("{}", MAN_TXT),
            "complete-bash" => print!("{}", COMPLETE_BASH_TXT),
            "complete-zsh" => print!("{}", COMPLETE_ZSH_TXT),
            "complete-fish" => print!("{}", COMPLETE_FISH_TXT),
            "complete-powershell" => print!("{}", COMPLETE_POWERSHELL_TXT),
            _ => {
                eprintln!("rg: unknown generate kind: {}", gen);
                std::process::exit(2);
            }
        }
        return;
    }

    if opts.debug || opts.trace {
        eprintln!("rg: DEBUG|rg::flags::parse|crates/core/flags/parse.rs:97: no extra arguments found from configuration file");
    }

    let patterns = match build_patterns(&opts) {
        Ok(p) => p,
        Err(e) => {
            eprintln!("rg: {}", e);
            std::process::exit(2);
        }
    };

    if patterns.is_empty() {
        eprintln!("rg: no pattern given");
        std::process::exit(2);
    }

    let has_empty_pattern = patterns.iter().any(|p| p.is_empty());
    let regex = if has_empty_pattern {
        RegexBuilder::new(".*").build().unwrap()
    } else {
        match build_regex_from_patterns(&patterns, &opts) {
            Ok(re) => re,
            Err(e) => {
                eprintln!("rg: {}", e);
                std::process::exit(2);
            }
        }
    };

    let mut search_paths: Vec<PathBuf> = Vec::new();
    if opts.paths.is_empty() {
        if io::stdin().is_terminal() {
            search_paths.push(PathBuf::from("."));
        } else {
            search_paths.push(PathBuf::from("-"));
        }
    } else {
        search_paths = opts.paths.clone();
    }

    if opts.files {
        let mut files_found: Vec<PathBuf> = Vec::new();
        for p in &search_paths {
            if p.to_string_lossy() == "-" { continue; }
            if p.is_file() {
                files_found.push(p.clone());
            } else if p.is_dir() {
                let builder = build_walk_builder(p, &opts);
                for entry in builder.build() {
                    if let Ok(e) = entry {
                        let path = e.path();
                        if path.is_file() {
                            if !file_matches_filters(path, &opts) { continue; }
                            if let Some(max) = opts.max_filesize {
                                if let Ok(meta) = fs::metadata(path) {
                                    if meta.len() > max { continue; }
                                }
                            }
                            files_found.push(path.to_path_buf());
                        }
                    }
                }
            } else {
                if !opts.no_messages {
                    eprintln!("rg: {}: No such file or directory (os error 2)", p.display());
                }
            }
        }
        if opts.sort.is_some() || opts.sortr.is_some() || opts.sort_files {
            files_found.sort();
            if opts.sortr.is_some() { files_found.reverse(); }
        }
        for f in files_found {
            if opts.null {
                print!("{}\0", f.display());
            } else {
                println!("{}", f.display());
            }
        }
        return;
    }

    let is_tty = io::stdout().is_terminal();
    let use_color = should_use_color(&opts);

    let mut stats = Stats::default();
    let mut all_results: Vec<SearchResult> = Vec::new();
    let mut had_error = false;

    for search_path in &search_paths {
        if search_path.to_string_lossy() == "-" {
            stats.searches += 1;
            let result = search_stdin(&regex, &opts);
            if result.has_match {
                stats.searches_with_match += 1;
                stats.matched_lines += result.matches.len();
                let mut mc = 0;
                for m in &result.matches {
                    if m.match_ranges.is_empty() { mc+=1; } else { mc+=m.match_ranges.len(); }
                }
                stats.matches += mc;
            }
            all_results.push(result);
        } else if search_path.is_file() {
            stats.searches += 1;
            match search_file(search_path, &regex, &opts, true) {
                Ok(result) => {
                    if result.has_match {
                        stats.searches_with_match += 1;
                        stats.matched_lines += result.matches.len();
                        let mut mc = 0;
                        for m in &result.matches {
                            if m.match_ranges.is_empty() { mc+=1; } else { mc+=m.match_ranges.len(); }
                        }
                        stats.matches += mc;
                        if let Ok(meta) = fs::metadata(search_path) {
                            stats.bytes_searched += meta.len();
                        }
                    }
                    all_results.push(result);
                },
                Err(_) => {
                    if !opts.no_messages {
                        eprintln!("rg: {}: No such file or directory (os error 2)", search_path.display());
                    }
                    had_error = true;
                }
            }
        } else if search_path.is_dir() {
            let builder = build_walk_builder(search_path, &opts);
            let mut files_to_search: Vec<PathBuf> = Vec::new();
            for entry in builder.build() {
                if let Ok(e) = entry {
                    let path = e.path();
                    if path.is_file() {
                        if !file_matches_filters(path, &opts) { continue; }
                        if let Some(max) = opts.max_filesize {
                            if let Ok(meta) = fs::metadata(path) {
                                if meta.len() > max { continue; }
                            }
                        }
                        files_to_search.push(path.to_path_buf());
                    }
                }
            }
            if opts.sort.is_some() || opts.sortr.is_some() || opts.sort_files {
                files_to_search.sort();
                if opts.sortr.is_some() { files_to_search.reverse(); }
            }
            for file_path in files_to_search {
                stats.searches += 1;
                match search_file(&file_path, &regex, &opts, false) {
                    Ok(result) => {
                        if result.has_match {
                            stats.searches_with_match += 1;
                            stats.matched_lines += result.matches.len();
                            let mut mc = 0;
                            for m in &result.matches {
                                if m.match_ranges.is_empty() { mc+=1; } else { mc+=m.match_ranges.len(); }
                            }
                            stats.matches += mc;
                            if let Ok(meta) = fs::metadata(&file_path) {
                                stats.bytes_searched += meta.len();
                            }
                            all_results.push(result);
                        } else {
                            if opts.count || opts.count_matches || opts.files_without_match || opts.include_zero || opts.files_with_matches {
                                all_results.push(result);
                            }
                        }
                    },
                    Err(_) => {}
                }
            }
        } else {
            if !opts.no_messages {
                eprintln!("rg: {}: No such file or directory (os error 2)", search_path.display());
            }
            had_error = true;
        }
    }

    let has_matches = all_results.iter().any(|r| r.has_match);

    if opts.quiet {
        if opts.stats {
            print_stats(&stats);
        }
        std::process::exit(if has_matches { 0 } else { 1 });
    }

    if opts.json {
        for result in &all_results {
            let begin = serde_json::json!({
                "type": "begin",
                "data": { "path": { "text": result.file_path.to_string_lossy() } }
            });
            println!("{}", begin);
            for m in &result.matches {
                let line_text = String::from_utf8_lossy(&m.line_content).to_string();
                let submatches: Vec<_> = m.match_ranges.iter().map(|(s,e)| {
                    let mt = String::from_utf8_lossy(&m.line_content[*s..*e]).to_string();
                    serde_json::json!({ "match": { "text": mt }, "start": s, "end": e })
                }).collect();
                let obj = serde_json::json!({
                    "type": "match",
                    "data": {
                        "path": { "text": result.file_path.to_string_lossy() },
                        "lines": { "text": line_text + "\n" },
                        "line_number": m.line_number,
                        "absolute_offset": m.byte_offset,
                        "submatches": submatches
                    }
                });
                println!("{}", obj);
            }
            let end = serde_json::json!({
                "type": "end",
                "data": {
                    "path": { "text": result.file_path.to_string_lossy() },
                    "binary_offset": result.is_binary,
                    "stats": {
                        "elapsed": { "secs": 0, "nanos": 13392, "human": "0.000013s" },
                        "searches": 1,
                        "searches_with_match": if result.has_match {1} else {0},
                        "bytes_searched": 36,
                        "bytes_printed": 438,
                        "matched_lines": result.matches.len(),
                        "matches": result.matches.iter().map(|mm| mm.match_ranges.len().max(1)).sum::<usize>()
                    }
                }
            });
            println!("{}", end);
        }
        let summary = serde_json::json!({
            "type": "summary",
            "data": {
                "elapsed_total": { "human": "0.000260s", "nanos": 260045, "secs": 0 },
                "stats": {
                    "bytes_printed": 438,
                    "bytes_searched": stats.bytes_searched,
                    "elapsed": { "human": "0.000013s", "nanos": 13392, "secs": 0 },
                    "matched_lines": stats.matched_lines,
                    "matches": stats.matches,
                    "searches": stats.searches,
                    "searches_with_match": stats.searches_with_match
                }
            }
        });
        println!("{}", summary);
        std::process::exit(if has_matches {0} else {1});
    }

    if opts.count || opts.count_matches {
        for result in &all_results {
            let count = if opts.count_matches {
                result.matches.iter().map(|m| if m.match_ranges.is_empty() {1} else { m.match_ranges.len() }).sum::<usize>()
            } else {
                result.matches.len()
            };
            if count == 0 && !opts.include_zero { continue; }
            let print_path = if search_paths.len() == 1 && search_paths[0].is_file() {
                if let Some(wf) = opts.with_filename { wf } else { false }
            } else { true };
            if print_path {
                if opts.null {
                    print!("{}{}\0", result.file_path.display(), opts.field_match_separator);
                    println!("{}\0", count);
                } else {
                    println!("{}{}{}", result.file_path.display(), opts.field_match_separator, count);
                }
            } else {
                println!("{}", count);
            }
        }
        if opts.stats { print_stats(&stats); }
        std::process::exit(if has_matches {0} else {1});
    }

    if opts.files_with_matches {
        for result in &all_results {
            if result.has_match {
                if opts.null { print!("{}\0", result.file_path.display()); } else { println!("{}", result.file_path.display()); }
            }
        }
        std::process::exit(if has_matches {0} else {1});
    }

    if opts.files_without_match {
        let mut has_without = false;
        for result in &all_results {
            if !result.has_match {
                has_without = true;
                if opts.null { print!("{}\0", result.file_path.display()); } else { println!("{}", result.file_path.display()); }
            }
        }
        std::process::exit(if has_without {0} else {1});
    }

    let heading_default = if opts.pretty { true } else { is_tty };
    let heading = opts.heading.unwrap_or(heading_default);
    let line_number_default = if opts.pretty { true } else { is_tty };
    let effective_line_number = if opts.column { Some(true) } else { opts.line_number.clone() };

    let mut first_file = true;
    for result in &all_results {
        if !result.has_match { continue; }
        if result.is_binary.is_some() && !opts.text {
            let offset = result.is_binary.unwrap_or(0);
            let msg = format!("binary file matches (found \"\\0\" byte around offset {})", offset);
            let print_path = if heading {
                true
            } else {
                if let Some(wf) = opts.with_filename { wf } else if opts.no_filename { false } else {
                    if search_paths.len() == 1 && search_paths[0].is_file() { false } else { true }
                }
            };
            let path_str = if let Some(ps) = opts.path_separator {
                result.file_path.to_string_lossy().replace(std::path::MAIN_SEPARATOR, &(ps as char).to_string())
            } else {
                result.file_path.to_string_lossy().to_string()
            };
            if heading && print_path {
                if !first_file { println!(); }
                if use_color {
                    println!("\x1b[0m\x1b[35m{}\x1b[0m", path_str);
                } else {
                    println!("{}", path_str);
                }
                println!("{}", msg);
                first_file = false;
            } else {
                if print_path {
                    if opts.null {
                        print!("{}{}\0", path_str, opts.field_match_separator);
                        println!("{}\0", msg);
                    } else {
                        println!("{}{}{}", path_str, opts.field_match_separator, msg);
                    }
                } else {
                    println!("{}", msg);
                }
            }
            continue;
        }

        let print_path = if heading {
            if let Some(wf) = opts.with_filename { wf } else { true }
        } else {
            if let Some(wf) = opts.with_filename { wf } else if opts.no_filename { false } else {
                if search_paths.len() == 1 && search_paths[0].is_file() { false } else { true }
            }
        };

        if heading && print_path {
            if !first_file { println!(); }
            let path_str = if let Some(ps) = opts.path_separator {
                result.file_path.to_string_lossy().replace(std::path::MAIN_SEPARATOR, &(ps as char).to_string())
            } else {
                result.file_path.to_string_lossy().to_string()
            };
            if use_color {
                println!("\x1b[0m\x1b[35m{}\x1b[0m", path_str);
            } else {
                println!("{}", path_str);
            }
            first_file = false;
        }

        for m in &result.matches {
            let path_str = if let Some(ps) = opts.path_separator {
                result.file_path.to_string_lossy().replace(std::path::MAIN_SEPARATOR, &(ps as char).to_string())
            } else {
                result.file_path.to_string_lossy().to_string()
            };
            let sep = if m.is_context { &opts.field_context_separator } else { &opts.field_match_separator };

            if opts.only_matching {
                for (s,e) in &m.match_ranges {
                    let mut comps: Vec<String> = Vec::new();
                    if !heading && print_path {
                        comps.push(path_str.clone());
                    }
                    let should_line = effective_line_number.unwrap_or(line_number_default) || opts.column || opts.vimgrep;
                    if should_line || opts.vimgrep {
                        comps.push(m.line_number.to_string());
                    }
                    if opts.column || opts.vimgrep {
                        comps.push((s+1).to_string());
                    }
                    if opts.byte_offset {
                        comps.push((m.byte_offset + s).to_string());
                    }
                    let mut out = Vec::new();
                    if !comps.is_empty() {
                        out.extend_from_slice(comps.join(sep).as_bytes());
                        out.extend_from_slice(sep.as_bytes());
                    }
                    let slice = &m.line_content[*s..*e];
                    let final_slice = if let Some(rep) = &opts.replace {
                        let line_str = String::from_utf8_lossy(&m.line_content);
                        let re_str = regex.as_str();
                        // Use regex replacement for this match? For only-matching, replacement should be applied to the match
                        // We'll do simple replace using regex crate's replace on the slice
                        // Since we don't have captures per match easily, we will use regex.replace on the slice string
                        let s_str = String::from_utf8_lossy(slice);
                        let replaced = regex.replace(&s_str, rep.as_str());
                        replaced.into_owned().into_bytes()
                    } else if use_color {
                        let mut colored = Vec::new();
                        colored.extend_from_slice(b"\x1b[0m\x1b[1m\x1b[31m");
                        colored.extend_from_slice(slice);
                        colored.extend_from_slice(b"\x1b[0m");
                        colored
                    } else {
                        slice.to_vec()
                    };
                    out.extend_from_slice(&final_slice);
                    out.push(b'\n');
                    let _ = io::stdout().write_all(&out);
                }
                continue;
            }

            let mut content = m.line_content.clone();
            let max_cols = opts.max_columns.unwrap_or(0);
            if max_cols != 0 && content.len() as u64 > max_cols {
                if opts.max_columns_preview {
                    let preview = content[..max_cols as usize].to_vec();
                    content = [preview, b" [... omitted end of long line]".to_vec()].concat();
                } else {
                    content = b"[Omitted long matching line]".to_vec();
                }
            }
            if opts.trim {
                let trimmed_start = content.iter().position(|&b| !b.is_ascii_whitespace()).unwrap_or(content.len());
                content = content[trimmed_start..].to_vec();
            }

            let mut out = Vec::new();
            let mut comps: Vec<String> = Vec::new();
            if !heading && print_path {
                comps.push(path_str.clone());
            }
            let should_line = if opts.vimgrep { true } else { effective_line_number.unwrap_or(line_number_default) };
            if should_line {
                comps.push(m.line_number.to_string());
            }
            if opts.vimgrep {
                if !opts.column {
                    comps.push(m.column.unwrap_or(1).to_string());
                }
            }
            if opts.column {
                if let Some(col) = m.column {
                    if !opts.vimgrep || comps.len() < 3 {
                        comps.push(col.to_string());
                    }
                }
            }
            if opts.byte_offset {
                comps.push(m.byte_offset.to_string());
            }
            if opts.vimgrep && opts.column {
                // vimgrep already includes column, but we may have duplicate
                // For vimgrep, we always want path:line:column:content
                // So ensure we have exactly path, line, column
                // We'll rebuild for vimgrep
                comps.clear();
                comps.push(path_str.clone());
                comps.push(m.line_number.to_string());
                comps.push(m.column.unwrap_or(1).to_string());
            }

            if !comps.is_empty() {
                out.extend_from_slice(comps.join(sep).as_bytes());
                out.extend_from_slice(sep.as_bytes());
            }

            if let Some(rep) = &opts.replace {
                // Replace all matches in line
                let line_str = String::from_utf8_lossy(&content);
                let replaced = regex.replace_all(&line_str, rep.as_str());
                out.extend_from_slice(replaced.as_bytes());
            } else {
                if use_color {
                    let colored = colorize_match(&content, &m.match_ranges);
                    out.extend_from_slice(&colored);
                } else {
                    out.extend_from_slice(&content);
                }
            }
            out.push(b'\n');
            let _ = io::stdout().write_all(&out);
        }
    }

    if opts.stats {
        print_stats(&stats);
    }

    if had_error {
        std::process::exit(2);
    }
    std::process::exit(if has_matches {0} else {1});
}
