fn parse_filesize(s: &str) -> Option<u64> {
    let s = s.trim();
    if s.is_empty() { return None; }
    let mut num_part = String::new();
    let mut suffix_part = String::new();
    for c in s.chars() {
        if c.is_ascii_digit() {
            if suffix_part.is_empty() { num_part.push(c); } else { return None; }
        } else { suffix_part.push(c); }
    }
    if num_part.is_empty() { return None; }
    let num: u64 = num_part.parse().ok()?;
    let mult = match suffix_part.to_ascii_lowercase().as_str() {
        "" => 1,
        "k" => 1024,
        "m" => 1024*1024,
        "g" => 1024*1024*1024,
        "ki" | "kib" => 1024,
        "mi" | "mib" => 1024*1024,
        "gi" | "gib" => 1024*1024*1024,
        _ => return None,
    };
    Some(num * mult)
}

fn unescape_separator(s: &str) -> String {
    let mut result = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            if let Some(&next) = chars.peek() {
                match next {
                    'n' => { result.push('\n'); chars.next(); },
                    'r' => { result.push('\r'); chars.next(); },
                    't' => { result.push('\t'); chars.next(); },
                    'x' => {
                        chars.next();
                        let mut hex = String::new();
                        for _ in 0..2 {
                            if let Some(&h) = chars.peek() {
                                if h.is_ascii_hexdigit() { hex.push(h); chars.next(); } else { break; }
                            }
                        }
                        if !hex.is_empty() { if let Ok(b) = u8::from_str_radix(&hex, 16) { result.push(b as char); } }
                    },
                    _ => { result.push(next); chars.next(); }
                }
            } else { result.push('\\'); }
        } else { result.push(c); }
    }
    result
}

fn read_config_file(path: &Path) -> Vec<String> {
