    replace: Option<String>,
    sort: Option<String>,
    sortr: Option<String>,
    sort_files: bool,
    trim: bool,
    vimgrep: bool,
    max_columns: Option<u64>,
    max_columns_preview: bool,
    include_zero: bool,
    color: String,
    path_separator: Option<u8>,
    passthru: bool,
    count: bool,
    count_matches: bool,
    files_with_matches: bool,
    files_without_match: bool,
    json: bool,
    files: bool,
    debug: bool,
    trace: bool,
    no_ignore_messages: bool,
    no_messages: bool,
    stats: bool,
